SELECT workspace_id,root_path,display_name,trust,revision,updated_at_ms,kind FROM
ja_workspace

    kind=#{kind}
    AND (updated_at_ms<#{cursorTime,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT} OR (updated_at_ms=#{cursorTime,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT} AND workspace_id<#{cursorId}))

ORDER BY updated_at_ms DESC,workspace_id DESC LIMIT #{limit}

mapper.update:
UPDATE ja_conversation_thread SET title=#{title},title_source=#{titleSource},updated_at_ms=#{occurredAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT}
WHERE thread_id=#{threadId} AND deleted_at_ms IS NULL


        AND revision>=#{expectedRevision} AND title_source='PLACEHOLDER'


        AND revision=#{expectedRevision}

UPDATE ja_conversation_thread SET provider_id=#{providerId},model_id=#{modelId},reasoning_level=#{reasoningLevel},
access_mode=#{accessMode},collaboration_mode=#{collaborationMode},updated_at_ms=#{occurredAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT}
WHERE thread_id=#{threadId} AND revision=#{expectedRevision} AND deleted_at_ms IS NULL

UPDATE ja_conversation_thread SET pinned_at_ms=#{pinnedAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT},updated_at_ms=#{occurredAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT}
WHERE thread_id=#{threadId} AND revision=#{expectedRevision}
AND archived_at_ms IS NULL AND deleted_at_ms IS NULL

UPDATE ja_conversation_thread

    SET deleted_at_ms=#{occurredAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT},pinned_at_ms=NULL,
    SET archived_at_ms=#{occurredAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT},pinned_at_ms=NULL,

updated_at_ms=#{occurredAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT}
WHERE thread_id=#{threadId} AND revision=#{expectedRevision} AND deleted_at_ms IS NULL
AND archived_at_ms IS NULL
AND NOT EXISTS (
    SELECT 1 FROM ja_conversation_lineage
    WHERE child_thread_id=#{threadId} OR parent_thread_id=#{threadId}
    )

UPDATE ja_conversation_thread SET archived_at_ms=NULL,pinned_at_ms=NULL,updated_at_ms=#{occurredAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT}
WHERE thread_id=#{threadId} AND revision=#{expectedRevision}
AND archived_at_ms IS NOT NULL AND deleted_at_ms IS NULL

mapper.select:
SELECT item_id,item_kind,created_at_ms,turn_id,call_id,tool_name,tool_ordinal,tool_state,message_kind, preview_text,total_characters,model_round,presentation_json,approval_id,decision,expires_at_ms,attachments_json, context_references_json,source_thread_id,source_title,context_message_id,context_message_ordinal, timeline_sequence,turn_sequence,semantic_order,ordinal_order FROM ordered_items
WHERE (created_at_ms,semantic_order,ordinal_order,item_id)>( #{cursorTime,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT}, (SELECT semantic_order FROM ordered_items WHERE item_id=#{cursorId}), (SELECT ordinal_order FROM ordered_items WHERE item_id=#{cursorId}), #{cursorId})
ORDER BY created_at_ms,semantic_order,ordinal_order,item_id LIMIT #{limit}

SELECT item_id,item_kind,created_at_ms,turn_id,call_id,tool_name,tool_ordinal,tool_state,message_kind, preview_text,total_characters,model_round,presentation_json,approval_id,decision,expires_at_ms,attachments_json, context_references_json,source_thread_id,source_title,context_message_id,context_message_ordinal, timeline_sequence,turn_sequence,semantic_order,ordinal_order FROM ordered_items
WHERE (created_at_ms,semantic_order,ordinal_order,item_id)<( #{cursorTime,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT}, (SELECT semantic_order FROM ordered_items WHERE item_id=#{cursorId}), (SELECT ordinal_order FROM ordered_items WHERE item_id=#{cursorId}), #{cursorId})
ORDER BY created_at_ms DESC,semantic_order DESC,ordinal_order DESC,item_id DESC LIMIT #{limit}

SELECT item_id,item_kind,created_at_ms,turn_id,call_id,tool_name,tool_ordinal,tool_state,message_kind, preview_text,total_characters,model_round,presentation_json,approval_id,decision,expires_at_ms,attachments_json, context_references_json,source_thread_id,source_title,context_message_id,context_message_ordinal, timeline_sequence,turn_sequence,semantic_order,ordinal_order FROM ordered_items WHERE ( (context_message_ordinal IS NOT NULL AND (turn_sequence,context_message_ordinal,semantic_order,ordinal_order,timeline_sequence,item_id)<=( (SELECT turn_sequence FROM ordered_items WHERE item_id=#{boundaryItemId}), (SELECT context_message_ordinal FROM ordered_items WHERE item_id=#{boundaryItemId}), (SELECT semantic_order FROM ordered_items WHERE item_id=#{boundaryItemId}), (SELECT ordinal_order FROM ordered_items WHERE item_id=#{boundaryItemId}), (SELECT timeline_sequence FROM ordered_items WHERE item_id=#{boundaryItemId}),#{boundaryItemId})) OR (context_message_ordinal IS NULL AND ( turn_sequence < (SELECT turn_sequence FROM ordered_items WHERE item_id=#{boundaryItemId}) OR (turn_sequence=(SELECT turn_sequence FROM ordered_items WHERE item_id=#{boundaryItemId}) AND timeline_sequence <= (SELECT timeline_sequence FROM ordered_items WHERE item_id=#{boundaryItemId})))) )
AND (turn_sequence,COALESCE(context_message_ordinal,0),semantic_order,ordinal_order,timeline_sequence,item_id)>( #{cursorTurnSequence},COALESCE(#{cursorContextMessageOrdinal},0),#{cursorSemanticOrder},#{cursorOrdinalOrder}, #{cursorTimelineSequence},#{cursorItemId})
ORDER BY turn_sequence,COALESCE(context_message_ordinal,0),semantic_order,ordinal_order,timeline_sequence,item_id LIMIT #{limit}

SELECT cursor_json FROM agent_execution
WHERE tenant_id=#{tenantId} AND thread_id=#{threadId} AND turn_id=#{turnId}
AND user_id=#{userId}
AND mutation_version=#{mutationVersion} AND state=#{state}
AND cursor_schema_version=#{schemaVersion}

mapper.insert:
INSERT INTO ja_turn_change_set(thread_id,turn_id,workspace_id,change_set_json,artifact_id,committed_at_ms)
SELECT #{threadId},#{turnId},#{workspaceId},#{changeSetJson},#{artifactId},#{occurredAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT}
WHERE EXISTS(SELECT 1 FROM ja_conversation_turn x JOIN ja_conversation_thread t ON t.thread_id=x.thread_id
WHERE x.turn_id=#{turnId} AND x.thread_id=#{threadId} AND t.workspace_id=#{workspaceId}
AND x.state IN ('COMPLETED','FAILED','CANCELLED'))
